<?= $this->extend('customer/layouts/main') ?><?= $this->section('content') ?><main class="portal-main portal-container wizard-container" id="main-content"><a class="back-link" href="<?= url_to('customer.properties') ?>">Back to my properties</a><div class="page-header"><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>List your property for resale.</h1><p>Begin with a verified property from your portfolio.</p></div></div><ol class="wizard-stepper"><?php foreach(['Property','Price','Selling Method','Review']as$i=>$label): ?><li class="<?= $i===0?'active':'' ?>"><span class="step-number"><?= $i+1 ?></span><span><small>STEP <?= $i+1 ?></small><strong><?= $label ?></strong></span></li><?php endforeach ?></ol><section class="surface-card wizard-panel"><h2><?= $selectedProperty?'Your current ownership is verified.':'Choose a property from My Properties.' ?></h2><?php if($selectedProperty): ?><h3><?= esc($selectedProperty['project'].' - '.$selectedProperty['plot']) ?></h3><p><?= esc($selectedProperty['erp'].' / '.$selectedProperty['head'].' / '.$selectedProperty['subhead']) ?></p><p><?= esc($selectedProperty['size']) ?></p><?php if($selectedProperty['floor']!==''): ?><p>Floor: <?= esc($selectedProperty['floor']) ?></p><?php endif ?><section class="my-4"><h3>Authorized Agency</h3><?php if($agencyOptions): ?><form data-agency-selection-form data-reference="<?= esc($selectedProperty['id'],'attr') ?>" data-endpoint="<?= site_url('customer/resale/agency') ?>"><label class="form-label" for="resaleAgency">Choose an agency authorized for this portfolio</label><select class="form-select mb-3" id="resaleAgency" name="agency_link_id" required><option value="">Select an authorized agency</option><?php foreach($agencyOptions as$agency): ?><option value="<?= $agency['agency_erp_link_id'] ?>"><?= esc($agency['agency_name']) ?></option><?php endforeach ?></select><button class="btn btn-outline" type="submit">Confirm Agency</button><p data-agency-result class="mt-3" role="